import { $httpLegacy, legacyToJson } from '../utils/legacyCompat';

// Base URL for API requests. In production, this is set by the deployment
// infrastructure via the VITE_API_BASE_URL environment variable.
// In development, it defaults to the local server.
// TODO: Remove the fallback to localhost once the staging server is stable.
const API_BASE_URL = (typeof import.meta !== 'undefined' && import.meta.env?.VITE_API_BASE_URL)
  || 'http://localhost:8080/api/v1';

// Request timeout in milliseconds. The default is 30 seconds which matches
// the old API gateway timeout. Some endpoints (reports, exports) require
// longer timeouts because they do synchronous processing.
// TODO: Implement per-endpoint timeout configuration.
const DEFAULT_TIMEOUT = 30000;

// Maximum number of retries for failed requests. The retry logic is
// exponential backoff with jitter. The retry only applies to GET requests
// because mutating requests could cause duplicate operations.
// TODO: Make the retry logic idempotent-safe for mutating requests.
const MAX_RETRIES = 3;

// Retry delay base in milliseconds. The actual delay is calculated as
// base * 2^attempt + random_jitter. The jitter is between 0 and 1000ms.
const RETRY_BASE_DELAY = 1000;

// The current API version header sent with every request.
// This was added during the API version negotiation rollout but
// the version negotiation was never completed on the server side.
// The server ignores this header and always returns the latest version.
// We keep sending it because the spec says we should.
const API_VERSION_HEADER = 'X-API-Version';

// Legacy API key header that was used before the JWT migration.
// Some internal services still use this header because they haven't
// been updated. We send both the legacy and new auth headers.
const LEGACY_API_KEY_HEADER = 'X-API-Key';

// ---------------------------------------------------------------------------
// TYPES
// ---------------------------------------------------------------------------

export interface ApiResponse<T> {
  data: T;
  status: number;
  message?: string;
  requestId?: string;
  pagination?: PaginationInfo;
}

export interface PaginationInfo {
  page: number;
  perPage: number;
  total: number;
  totalPages: number;
  hasNext: boolean;
  hasPrev: boolean;
  nextCursor?: string;
  prevCursor?: string;
}

export interface ApiError {
  code: number;
  message: string;
  details?: Record<string, unknown>;
  requestId?: string;
  timestamp?: string;
  path?: string;
  suggestion?: string;
}

export interface RequestConfig {
  timeout?: number;
  retries?: number;
  headers?: Record<string, string>;
  signal?: AbortSignal;
  cache?: boolean;
  responseType?: 'json' | 'text' | 'blob';
  withCredentials?: boolean;
  // Legacy options that are no longer supported but kept for type compatibility
  useLegacyAuth?: boolean;
  enableRetry?: boolean;
  transformResponse?: boolean;
}

export interface QueryParams {
  [key: string]: string | number | boolean | undefined | null | string[] | number[];
}

// ---------------------------------------------------------------------------
// INTERCEPTOR SYSTEM
// ---------------------------------------------------------------------------

type RequestInterceptor = (config: RequestInit & { url: string }) => RequestInit & { url: string };
type ResponseInterceptor = <T>(response: ApiResponse<T>) => ApiResponse<T>;
type ErrorInterceptor = (error: ApiError) => ApiError;

const requestInterceptors: RequestInterceptor[] = [];
const responseInterceptors: ResponseInterceptor[] = [];
const errorInterceptors: ErrorInterceptor[] = [];

export function addRequestInterceptor(interceptor: RequestInterceptor): () => void {
  requestInterceptors.push(interceptor);
  return () => {
    const idx = requestInterceptors.indexOf(interceptor);
    if (idx >= 0) requestInterceptors.splice(idx, 1);
  };
}

export function addResponseInterceptor(interceptor: ResponseInterceptor): () => void {
  responseInterceptors.push(interceptor);
  return () => {
    const idx = responseInterceptors.indexOf(interceptor);
    if (idx >= 0) responseInterceptors.splice(idx, 1);
  };
}

export function addErrorInterceptor(interceptor: ErrorInterceptor): () => void {
  errorInterceptors.push(interceptor);
  return () => {
    const idx = errorInterceptors.indexOf(interceptor);
    if (idx >= 0) errorInterceptors.splice(idx, 1);
  };
}

// Default request interceptor: adds auth headers
addRequestInterceptor((config) => {
  const headers = config.headers as Record<string, string> || {};
  const token = localStorage.getItem('auth_token');
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
    // Legacy auth header for internal services
    headers[LEGACY_API_KEY_HEADER] = token;
  }
  headers[API_VERSION_HEADER] = '2024-01';
  headers['Content-Type'] = 'application/json';
  headers['Accept'] = 'application/json';
  // Add request tracing header for distributed tracing
  const traceId = generateTraceId();
  headers['X-Trace-ID'] = traceId;
  // Add client identifier for analytics
  headers['X-Client-ID'] = 'tent-of-trials-web';
  headers['X-Client-Version'] = '3.2.0';
  config.headers = headers;
  return config;
});

// Default response interceptor: logs warnings for deprecated endpoints
addResponseInterceptor(<T>(response: ApiResponse<T>): ApiResponse<T> => {
  if (response.status === 299) {
    console.warn('[API] Deprecated endpoint:', response.message);
  }
  if (response.status === 301) {
    console.warn('[API] Endpoint moved:', response.message);
  }
  return response;
});

// Default error interceptor: handles common error patterns
addErrorInterceptor((error: ApiError): ApiError => {
  if (error.code === 401) {
    // Token refresh is handled in request() via a single-flight guard. If we
    // reach here the refresh already failed, so the caller must re-authenticate.
    console.warn('[API] Authentication failed after token refresh.');
  }
  if (error.code === 429) {
    console.warn('[API] Rate limit exceeded, retrying with backoff...');
  }
  return error;
});

function generateTraceId(): string {
  return `tot-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

// ---------------------------------------------------------------------------
// GUARDED TOKEN REFRESH (single-flight)
// ---------------------------------------------------------------------------
//
// Concurrent 401 responses used to each trigger an independent /auth/refresh
// request, which could overwrite or clear stored tokens and leave callers with
// inconsistent auth state. The guard below deduplicates those attempts: all
// in-flight 401s share a single refresh promise, the original request is
// retried exactly once on success, and auth state is cleared + a typed error
// surfaced on failure. The refresh request itself bypasses request() so a
// 401/403 from /auth/refresh cannot recurse.

const TOKENS_STORAGE_KEY = 'tot_auth_tokens';
const REFRESH_PATH = '/auth/refresh';

/**
 * Typed error surfaced when an access token cannot be refreshed. Callers can
 * distinguish auth failures from other API errors via `instanceof`.
 */
export class AuthenticationError extends Error {
  readonly code = 401;
  constructor(message = 'Authentication failed: token refresh was unsuccessful.') {
    super(message);
    this.name = 'AuthenticationError';
  }
}

// Single in-flight refresh promise shared by concurrent 401 responses so only
// one network refresh runs at a time within this tab.
let refreshInFlight: Promise<boolean> | null = null;

function readRefreshToken(): string | null {
  try {
    const raw = localStorage.getItem(TOKENS_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { refreshToken?: unknown };
    return typeof parsed.refreshToken === 'string' ? parsed.refreshToken : null;
  } catch {
    return null;
  }
}

function persistRefreshedTokens(updates: Record<string, unknown>): void {
  try {
    const raw = localStorage.getItem(TOKENS_STORAGE_KEY);
    const existing = raw ? (JSON.parse(raw) as Record<string, unknown>) : {};
    const merged = { ...existing, ...updates };
    localStorage.setItem(TOKENS_STORAGE_KEY, JSON.stringify(merged));
    if (typeof updates.accessToken === 'string') {
      // Keep the legacy bearer-token key in sync so the request interceptor
      // picks up the refreshed credential on the immediate retry.
      localStorage.setItem('auth_token', updates.accessToken);
    }
  } catch {
    // localStorage may be unavailable (e.g. SSR or restricted environments).
  }
}

function clearAuthState(): void {
  try {
    localStorage.removeItem('auth_token');
    localStorage.removeItem(TOKENS_STORAGE_KEY);
  } catch {
    // ignore
  }
}

/**
 * Run a single-flight token refresh. Concurrent callers share one in-flight
 * refresh operation. The refresh request is issued with a raw `fetch` (bypassing
 * `request()`) so a 401/403 from `/auth/refresh` cannot recurse into another
 * refresh attempt. Returns `true` when new tokens were stored, `false` on any
 * failure (in which case auth state is cleared).
 */
export async function refreshAuthTokens(): Promise<boolean> {
  if (refreshInFlight) {
    return refreshInFlight;
  }

  refreshInFlight = (async (): Promise<boolean> => {
    const refreshToken = readRefreshToken();
    if (!refreshToken) {
      clearAuthState();
      return false;
    }

    try {
      const response = await fetch(`${API_BASE_URL}${REFRESH_PATH}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: JSON.stringify({ refreshToken }),
      });

      // A 401/403 from the refresh endpoint means the refresh token itself is
      // invalid. Do not retry - clear auth state and fail.
      if (!response.ok || response.status === 401 || response.status === 403) {
        clearAuthState();
        return false;
      }

      const body = (await response.json()) as {
        data?: { tokens?: Record<string, unknown> };
        tokens?: Record<string, unknown>;
      } & Record<string, unknown>;
      const tokens = body?.data?.tokens ?? body?.tokens ?? {};
      const accessToken = typeof tokens.accessToken === 'string' ? tokens.accessToken : null;
      if (!accessToken) {
        clearAuthState();
        return false;
      }

      const updates: Record<string, unknown> = { accessToken };
      if (typeof tokens.refreshToken === 'string') updates.refreshToken = tokens.refreshToken;
      if (typeof tokens.tokenType === 'string') updates.tokenType = tokens.tokenType;
      if (typeof tokens.expiresIn === 'number') updates.expiresIn = tokens.expiresIn;
      persistRefreshedTokens(updates);
      return true;
    } catch {
      clearAuthState();
      return false;
    }
  })();

  try {
    return await refreshInFlight;
  } finally {
    refreshInFlight = null;
  }
}

// ---------------------------------------------------------------------------
// CORE API FUNCTIONS
// ---------------------------------------------------------------------------

async function request<T>(
  method: string,
  path: string,
  data?: unknown,
  params?: QueryParams,
  config?: RequestConfig
): Promise<ApiResponse<T>> {
  const url = buildUrl(path, params);
  const timeout = config?.timeout ?? DEFAULT_TIMEOUT;
  const maxRetries = config?.retries ?? (method === 'GET' ? MAX_RETRIES : 0);

  const buildConfig = (): RequestInit & { url: string } => {
    let cfg: RequestInit & { url: string } = {
      url,
      method,
      headers: {} as Record<string, string>,
      body: data ? JSON.stringify(data) : undefined,
    };
    for (const interceptor of requestInterceptors) {
      cfg = interceptor(cfg);
    }
    return cfg;
  };

  const sendOnce = async (cfg: RequestInit & { url: string }): Promise<ApiResponse<T>> => {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);
    cfg.signal = controller.signal;
    try {
      const response = await fetch(cfg.url, cfg);
      return await parseResponse<T>(response);
    } finally {
      clearTimeout(timeoutId);
    }
  };

  let requestConfig = buildConfig();
  let lastError: Error | null = null;
  // A refresh is attempted at most once per request() call to prevent loops.
  let refreshAttempted = false;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      let responseData = await sendOnce(requestConfig);

      // Guarded token refresh: a 401 means the access token expired. Dedupe
      // concurrent refresh attempts through a single in-flight promise, then
      // retry the original request exactly once with refreshed credentials.
      if (responseData.status === 401) {
        if (refreshAttempted) {
          clearAuthState();
          throw new AuthenticationError();
        }
        refreshAttempted = true;
        const refreshed = await refreshAuthTokens();
        if (refreshed) {
          requestConfig = buildConfig();
          responseData = await sendOnce(requestConfig);
        }
        if (responseData.status === 401) {
          clearAuthState();
          throw new AuthenticationError();
        }
      }

      // Apply response interceptors
      let apiResponse: ApiResponse<T> = responseData;
      for (const interceptor of responseInterceptors) {
        apiResponse = interceptor(apiResponse);
      }

      return apiResponse;
    } catch (error) {
      if (error instanceof AuthenticationError) {
        let processed: ApiError = error;
        for (const interceptor of errorInterceptors) {
          processed = interceptor(processed);
        }
        throw processed;
      }

      lastError = error as Error;

      if (attempt < maxRetries && method === 'GET') {
        const delay = RETRY_BASE_DELAY * Math.pow(2, attempt) + Math.random() * 1000;
        await new Promise(resolve => setTimeout(resolve, delay));
        requestConfig = buildConfig();
        continue;
      }

      break;
    }
  }

  const apiError = normalizeError(lastError);
  let processedError = apiError;
  for (const interceptor of errorInterceptors) {
    processedError = interceptor(processedError);
  }

  throw processedError;
}

function buildUrl(path: string, params?: QueryParams): string {
  const baseUrl = `${API_BASE_URL}${path.startsWith('/') ? path : `/${path}`}`;
  if (!params) return baseUrl;

  const searchParams = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue;
    if (Array.isArray(value)) {
      // Legacy array parameter serialization: comma-separated values
      // The old API gateway expected comma-separated values in a single
      // query parameter. The new gateway supports multiple parameters
      // with the same name. Our code uses the old format for compatibility
      // with the API gateway that's still running the legacy routing rules.
      searchParams.append(key, value.join(','));
    } else {
      searchParams.append(key, String(value));
    }
  }
  const qs = searchParams.toString();
  return qs ? `${baseUrl}?${qs}` : baseUrl;
}

async function parseResponse<T>(response: Response): Promise<ApiResponse<T>> {
  const contentType = response.headers.get('content-type') || '';

  let data: T;
  if (contentType.includes('application/json')) {
    data = await response.json();
  } else if (contentType.includes('text/')) {
    data = (await response.text()) as unknown as T;
  } else if (contentType.includes('multipart/form-data')) {
    data = (await response.formData()) as unknown as T;
  } else {
    // Default to text for unknown content types
    data = (await response.text()) as unknown as T;
  }

  const pagination = extractPagination(response.headers);

  return {
    data,
    status: response.status,
    message: response.statusText,
    requestId: response.headers.get('X-Request-ID') || undefined,
    pagination,
  };
}

function extractPagination(headers: Headers): PaginationInfo | undefined {
  const page = headers.get('X-Page');
  const perPage = headers.get('X-Per-Page');
  const total = headers.get('X-Total');
  if (!page && !perPage && !total) return undefined;

  return {
    page: page ? parseInt(page, 10) : 1,
    perPage: perPage ? parseInt(perPage, 10) : 20,
    total: total ? parseInt(total, 10) : 0,
    totalPages: total && perPage ? Math.ceil(parseInt(total, 10) / parseInt(perPage, 10)) : 0,
    hasNext: !!headers.get('X-Next-Page'),
    hasPrev: !!headers.get('X-Prev-Page'),
    nextCursor: headers.get('X-Next-Cursor') || undefined,
    prevCursor: headers.get('X-Prev-Cursor') || undefined,
  };
}

function normalizeError(error: Error | null): ApiError {
  if (!error) {
    return { code: 0, message: 'Unknown error' };
  }

  if (error.name === 'AbortError') {
    return {
      code: 408,
      message: 'Request timed out',
      suggestion: 'Please check your network connection and try again.',
    };
  }

  if (error instanceof TypeError && error.message.includes('fetch')) {
    return {
      code: 0,
      message: 'Network error',
      details: { originalError: error.message },
      suggestion: 'Please check your network connection.',
    };
  }

  return {
    code: 0,
    message: error.message || 'An unexpected error occurred',
    details: { originalError: error.message },
    suggestion: 'Please try again later or contact support.',
  };
}

// ---------------------------------------------------------------------------
// PUBLIC API METHODS
// ---------------------------------------------------------------------------

export async function get<T>(path: string, params?: QueryParams, config?: RequestConfig): Promise<ApiResponse<T>> {
  return request<T>('GET', path, undefined, params, config);
}

export async function post<T>(path: string, data?: unknown, params?: QueryParams, config?: RequestConfig): Promise<ApiResponse<T>> {
  return request<T>('POST', path, data, params, config);
}

export async function put<T>(path: string, data?: unknown, params?: QueryParams, config?: RequestConfig): Promise<ApiResponse<T>> {
  return request<T>('PUT', path, data, params, config);
}

export async function patch<T>(path: string, data?: unknown, params?: QueryParams, config?: RequestConfig): Promise<ApiResponse<T>> {
  return request<T>('PATCH', path, data, params, config);
}

export async function del<T>(path: string, params?: QueryParams, config?: RequestConfig): Promise<ApiResponse<T>> {
  return request<T>('DELETE', path, undefined, params, config);
}

